type User={id:string;email:string;role:string};type Review={id:string;decision:string;notes:string;createdAt:number};type Requirement={reviews?:Review[];submissions?:{id:string;createdAt:number}[];id:string;requirementCode?:string;contentVersion?:string;files:Material[];title:string;content:string;status:string;shareConsent:boolean;categoryId?:string|null;industry?:string;department?:string;difficulty?:string;implementationStatus?:string;expectedOutcome?:string;createdAt?:number;tags?:Tag[];images:{id:string;url:string}[]};type Tag={id:string;name:string;slug:string;group:string;color:string;active:boolean;sortOrder:number};type Case={id:string;requirementCode?:string;contentVersion?:string;files?:Material[];title:string;summary:string;status:string;categoryId?:string;industry?:string;department?:string;difficulty?:string;implementationStatus?:string;tags?:Tag[];prompts?:{type:string;content:string}[];images?:{id:string;url:string}[]};
function embeddedBusinessCategory(content:string){return content.match(/(?:^|\n)\s*业务分类\s*[：:]\s*([^\n]+)/)?.[1]?.trim()??'';}
function requirementSection(content:string,title:string){const escaped=title.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');return content.match(new RegExp(`(?:^|\\n)\\s*\\d+\\.\\s*${escaped}[^\\n]*\\n([\\s\\S]*?)(?=\\n\\s*\\d+\\.\\s|$)`))?.[1]?.replace(/\s+/g,' ').trim()??'';}
function requirementCategory(item:Requirement,categories:Category[]){return categories.find(category=>category.id===item.categoryId)?.name||embeddedBusinessCategory(item.content);}
function splitValues(value?:string){return(value??'').split(/[、,，/]/).map(item=>item.trim()).filter(Boolean);}
const reviewStatusLabels:Record<string,string>={submitted:'待审核',published:'已发布',rejected:'已退回',draft:'草稿'};
