function Requirements({admin=false}:{admin?:boolean}){
 return admin?<AdminRequirements/>:<MyRequirements/>;
}
function ReviewHistory({item}:{item:Requirement}){return <div className="space-y-2 text-sm"><h3 className="font-semibold">审核记录</h3>{item.reviews?.length?item.reviews.map(review=><div key={review.id} className="rounded-md bg-slate-50 p-3"><p>{review.decision==='reject'?'退回修改':'审核通过'} · {new Date(review.createdAt*1000).toLocaleString('zh-CN')}</p><p className="mt-1 whitespace-pre-wrap break-words">{review.notes||'无补充说明'}</p></div>):<p className="text-slate-600">尚无审核记录。</p>}{item.submissions?.map(event=><p key={event.id} className="text-slate-600">重新提交审核 · {new Date(event.createdAt*1000).toLocaleString('zh-CN')}</p>)}</div>;}
function EditMyRequirement(){const{id}=useParams();const{data,error,isLoading}=useQuery<Requirement>({queryKey:['requirements','detail',id],queryFn:()=>api('/requirements/'+id),gcTime:0});if(isLoading)return <Panel title="编辑我的需求">载入中…</Panel>;if(error||!data)return <Panel title="编辑我的需求"><ErrorLine error={error||'需求不存在'}/></Panel>;if(!['submitted','rejected'].includes(data.status))return <Panel title="编辑我的需求">当前需求不可修改。<Link to="/mine">返回我的需求</Link></Panel>;return <Submit key={data.id} editing={data}/>;}
function MyRequirements(){
 const{items:data,error,controls}=usePage<Requirement>('requirements','/requirements');
 const[open,setOpen]=useState<string|null>(null),[busy,setBusy]=useState<string|null>(null),[actionError,setActionError]=useState('');const qc=useQueryClient();
 return <Panel title="我的需求" action={<Link to="/submit"><Button><Plus size={16}/>新增需求</Button></Link>}><ErrorLine error={error||actionError}/>{controls}<div className="space-y-3">{data.map(item=><Card key={item.id}><CardContent><div className="flex flex-wrap gap-3 justify-between"><div className="min-w-0"><h3 className="font-semibold break-words">{item.title}</h3><p className="text-sm mt-1 text-slate-500 line-clamp-2 break-words">{item.content}</p><div className="text-xs text-slate-500 mt-2">{item.images.length} 张图片 · {item.industry||'行业未填写'} · {item.tags?.map(t=>t.name).join('、')||'无标签'} · {item.shareConsent?'允许脱敏共享':'不共享'}</div></div><div className="flex flex-wrap items-start gap-2"><span className="rounded-full bg-slate-100 px-3 py-1 text-xs">{reviewStatusLabels[item.status]??item.status}</span><Button size="sm" variant="outline" onClick={()=>setOpen(open===item.id?null:item.id)}>{open===item.id?'收起':'查看'}</Button>{['submitted','rejected'].includes(item.status)&&<Link to={'/mine/'+item.id+'/edit'}><Button size="sm" variant="outline">编辑需求</Button></Link>}{item.status==='rejected'&&<Button size="sm" disabled={busy!==null} onClick={async()=>{setBusy(item.id);setActionError('');try{await post('/requirements/'+item.id+'/resubmit',{});await qc.invalidateQueries({queryKey:['requirements']});}catch(e:any){setActionError(e.message);}finally{setBusy(null);}}}>{busy===item.id?'提交中…':'重新提交审核'}</Button>}</div></div>{item.status==='rejected'&&<div className="mt-3 rounded-md bg-amber-50 p-3 text-sm text-amber-900"><p className="font-medium">退回原因</p><p className="mt-1 whitespace-pre-wrap break-words">{item.reviews?.find(r=>r.decision==='reject')?.notes||'历史记录未填写原因，请联系管理员补充。'}</p><p className="mt-2">请先编辑并保存修改，再重新提交审核。</p></div>}{open===item.id&&<div className="border-t mt-4 pt-4 space-y-3"><RequirementDownloads id={item.id} code={item.requirementCode} version={item.contentVersion}/><Markdown content={item.content}/><MaterialList value={item.files??[]}/><div className="flex gap-2 flex-wrap">{item.images.map(im=><img key={im.id} src={im.url} alt="需求图片" className="h-28 max-w-full rounded-lg border"/>)}</div><ReviewHistory item={item}/></div>}</CardContent></Card>)}{data.length===0&&<p className="text-slate-500">暂无需求记录。</p>}</div></Panel>;
}
type RequirementDraft={title:string;content:string;categoryId:string;industry:string;department:string;difficulty:string;implementationStatus:string;expectedOutcome:string};
function RequirementQueue({categories,onOpen}:{categories:Category[];onOpen:(item:Requirement)=>void}){
 const[filter,setFilter]=useState(''),[categoryFilter,setCategoryFilter]=useState(''),[industryFilter,setIndustryFilter]=useState(''),[statusFilter,setStatusFilter]=useState(''),[consentFilter,setConsentFilter]=useState('');
 const{data:facets}=useData<{industries:string[];categories:{name:string;total:number}[];total:number;missingCategory:number;withoutTags:number;notAuthorized:number}>('requirements','/requirements/facets?scope=all');
 const categoryCounts=Object.fromEntries((facets?.categories??[]).map(x=>[x.name,x.total]));
 const categoryOptions=Object.keys(categoryCounts).sort((a,b)=>a.localeCompare(b,'zh-CN'));
 const industries=facets?.industries??[],statuses=Object.keys(reviewStatusLabels);
 const{items:filtered,total,controls}=usePage<Requirement>('requirements','/requirements?scope=all',Object.fromEntries(Object.entries({q:filter,category:categoryFilter,industry:industryFilter,status:statusFilter,consent:consentFilter}).filter(([,v])=>v)));
 const missingCategory=facets?.missingCategory??0,withoutTags=facets?.withoutTags??0,notAuthorized=facets?.notAuthorized??0;
 const hasFilters=!!(filter||categoryFilter||industryFilter||statusFilter||consentFilter);
 const clearFilters=()=>{setFilter('');setCategoryFilter('');setIndustryFilter('');setStatusFilter('');setConsentFilter('');};
 return <div className="space-y-4">
  <section className="rounded-lg border bg-white px-4 py-3" aria-label="需求数据概况">
   <div className="flex flex-wrap items-center gap-x-5 gap-y-2 text-sm"><span className="font-medium text-slate-900">{facets?.total??0} 条需求</span><span className="text-amber-700">{missingCategory} 条待映射分类</span><span className="text-slate-600">{withoutTags} 条无标签</span><span className="text-amber-700">{notAuthorized} 条未授权公开</span></div>
   {categoryOptions.length>0&&<div className="mt-3 flex flex-wrap gap-2" aria-label="按业务分类筛选">{categoryOptions.map(category=><button key={category} type="button" aria-pressed={categoryFilter===category} onClick={()=>setCategoryFilter(categoryFilter===category?'':category)} className={'rounded-full border px-3 py-1.5 text-xs transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-orange-500 '+(categoryFilter===category?'border-orange-300 bg-orange-50 font-medium text-orange-800':'border-slate-200 bg-white text-slate-600 hover:border-orange-200 hover:text-orange-800')}>{category} <span className="ml-1 tabular-nums text-slate-500">{categoryCounts[category]}</span></button>)}</div>}
  </section>
  <div className="grid gap-2 rounded-lg border bg-white p-3 sm:grid-cols-2 xl:grid-cols-[minmax(220px,1fr)_repeat(4,minmax(140px,auto))_auto]">
   <Input aria-label="搜索需求" className="sm:col-span-2 xl:col-span-1" placeholder="搜索标题、摘要、行业或部门" value={filter} onChange={event=>setFilter(event.target.value)}/>
   <select aria-label="业务分类筛选" className="w-full rounded-md border border-slate-300 bg-white px-3 py-2 text-sm" value={categoryFilter} onChange={event=>setCategoryFilter(event.target.value)}><option value="">全部分类</option>{categoryOptions.map(category=><option key={category} value={category}>{category}（{categoryCounts[category]}）</option>)}</select>
   <select aria-label="行业筛选" className="w-full rounded-md border border-slate-300 bg-white px-3 py-2 text-sm" value={industryFilter} onChange={event=>setIndustryFilter(event.target.value)}><option value="">全部行业</option>{industries.map(industry=><option key={industry} value={industry}>{industry}</option>)}</select>
   <select aria-label="审核状态筛选" className="w-full rounded-md border border-slate-300 bg-white px-3 py-2 text-sm" value={statusFilter} onChange={event=>setStatusFilter(event.target.value)}><option value="">全部状态</option>{statuses.map(status=><option key={status} value={status}>{reviewStatusLabels[status]??status}</option>)}</select>
   <select aria-label="共享授权筛选" className="w-full rounded-md border border-slate-300 bg-white px-3 py-2 text-sm" value={consentFilter} onChange={event=>setConsentFilter(event.target.value)}><option value="">全部授权状态</option><option value="authorized">允许脱敏共享</option><option value="private">仅私有</option></select>
   <Button type="button" variant="outline" disabled={!hasFilters} onClick={clearFilters}>清除筛选</Button>
  </div>
  <div className="flex items-center justify-between gap-3 text-sm text-slate-600"><p>本页 {filtered.length} 条 · 匹配 {total} 条需求</p>{hasFilters&&<button type="button" className="text-orange-700 underline underline-offset-2" onClick={clearFilters}>重置条件</button>}</div>
  {controls}
  <div className="overflow-x-auto rounded-lg border bg-white"><table className="w-full min-w-[1040px] text-left text-sm"><thead className="border-b bg-slate-50 text-slate-600"><tr><th scope="col" className="px-4 py-3 font-medium">需求与问题摘要</th><th scope="col" className="px-4 py-3 font-medium">分类 / 行业</th><th scope="col" className="px-4 py-3 font-medium">部门 / 实施信息</th><th scope="col" className="px-4 py-3 font-medium">审核与授权</th><th scope="col" className="px-4 py-3 font-medium">提交时间</th><th scope="col" className="px-4 py-3 font-medium">操作</th></tr></thead><tbody>{filtered.map(item=>{
   const category=requirementCategory(item,categories)||'未分类';
   const summary=requirementSection(item.content,'现有流程与痛点')||item.expectedOutcome||requirementSection(item.content,'核心需求')||item.content.replace(/\s+/g,' ');
   return <tr key={item.id} className="border-b last:border-0 align-top hover:bg-slate-50"><td className="max-w-[360px] px-4 py-3"><div className="font-medium text-slate-900">{item.title}</div><p className="mt-1 line-clamp-2 text-xs leading-relaxed text-slate-600">{summary}</p>{item.expectedOutcome&&<p className="mt-2 line-clamp-1 text-xs text-slate-500">预期：{item.expectedOutcome}</p>}</td><td className="px-4 py-3"><div className="font-medium text-slate-700">{category}</div>{!item.categoryId&&<span className="mt-1 inline-block rounded bg-amber-50 px-2 py-0.5 text-xs text-amber-800">系统分类待映射</span>}<div className="mt-1.5 text-xs leading-5 text-slate-500">{splitValues(item.industry).join('、')||'行业未填写'}</div></td><td className="px-4 py-3"><div className="text-slate-700">{splitValues(item.department).join('、')||'部门未填写'}</div><div className="mt-1 text-xs text-slate-500">难度：{difficultyLabels[item.difficulty??'']??'未评估'}</div><div className="mt-1 text-xs text-slate-500">实现：{implementationStatusLabels[item.implementationStatus??'']??'待实现'}</div></td><td className="px-4 py-3"><span className="inline-flex rounded-full bg-slate-100 px-2.5 py-1 text-xs font-medium text-slate-700">{reviewStatusLabels[item.status]??item.status}</span><div className={'mt-1.5 text-xs '+(item.shareConsent?'text-emerald-700':'text-amber-700')}>{item.shareConsent?'允许脱敏共享':'仅私有 · 未授权公开'}</div><div className="mt-1 text-xs text-slate-500">{item.tags?.length?item.tags.map(tag=>tag.name).join('、'):'尚无标签'}</div></td><td className="whitespace-nowrap px-4 py-3 text-xs text-slate-600">{item.createdAt?new Intl.DateTimeFormat('zh-CN',{dateStyle:'short',timeStyle:'short'}).format(item.createdAt*1000):'—'}</td><td className="px-4 py-3"><Button size="sm" variant="outline" onClick={()=>onOpen(item)}>编辑 / 审核</Button></td></tr>;
  })}</tbody></table>{filtered.length===0&&<p className="px-4 py-8 text-center text-sm text-slate-500">没有匹配的需求。调整筛选条件，或清除筛选查看全部记录。</p>}</div>
 </div>;
}
function AdminRequirements(){
 const[materials,setMaterials]=useState<Material[]>([]),[fileBusy,setFileBusy]=useState(false);
 const qc=useQueryClient();const{data:categories=[]}=useData<Category[]>('admin-requirement-categories','/categories');
 const[rejectNotes,setRejectNotes]=useState('');const[selected,setSelected]=useState<Requirement|null>(null),[draft,setDraft]=useState<RequirementDraft|null>(null),[preview,setPreview]=useState(false),[summary,setSummary]=useState(''),[rprompt,setRprompt]=useState(''),[bprompt,setBprompt]=useState(''),[approved,setApproved]=useState<string[]>([]),[actionError,setActionError]=useState(''),[notice,setNotice]=useState(''),[saving,setSaving]=useState(false);
 const openItem=(item:Requirement)=>{setRejectNotes('');setSelected(item);setMaterials(item.files??[]);setDraft({title:item.title,content:item.content,categoryId:item.categoryId??'',industry:item.industry??'',department:item.department??'',difficulty:item.difficulty??'',implementationStatus:item.implementationStatus??'pending',expectedOutcome:item.expectedOutcome??''});setPreview(false);setSummary(item.content.replace(/\b[\w.%+-]+@[\w.-]+\.[A-Za-z]{2,}\b/g,'[已脱敏邮箱]'));setRprompt(item.content);setBprompt('候选方案待讨论；请先澄清实际业务场景与需求。');setApproved([]);setActionError('');setNotice('');window.scrollTo(0,0);};
 const saveDraft=()=>{if(!selected||!draft)throw new Error('需求信息不可用');return patch('/requirements/'+selected.id,{...draft,fileIds:materials.map(f=>f.id),categoryId:draft.categoryId||null,industry:draft.industry||null,department:draft.department||null,difficulty:draft.difficulty||null,expectedOutcome:draft.expectedOutcome||null});};
 const save=async(e:React.FormEvent)=>{e.preventDefault();if(!selected||!draft)return;setSaving(true);setActionError('');setNotice('');try{await saveDraft();setSelected(await api<Requirement>('/requirements/'+selected.id));await qc.invalidateQueries({queryKey:['requirements']});setNotice('需求信息已保存');}catch(err:any){setActionError(err.message);}finally{setSaving(false);}};
 const setField=<K extends keyof RequirementDraft>(field:K,value:RequirementDraft[K])=>setDraft(current=>current?{...current,[field]:value}:current);
 return <Panel title="需求管理">{!selected?<RequirementQueue categories={categories} onOpen={openItem}/> :<div className="space-y-4"><div className="flex flex-wrap items-center justify-between gap-3"><Button variant="outline" onClick={()=>{setSelected(null);setDraft(null);setNotice('');setActionError('');}}>返回需求列表</Button><span className="rounded-full bg-slate-100 px-3 py-1 text-xs text-slate-700">{selected.status}</span></div><form className="rounded-lg border bg-white" onSubmit={save}><fieldset className="space-y-4 p-4 md:p-6"><legend className="px-2 text-base font-semibold text-slate-900">基本信息</legend>{draft&&<><div><label className="mb-1.5 block text-sm font-medium" htmlFor="requirement-title">需求标题</label><Input id="requirement-title" required minLength={2} maxLength={180} value={draft.title} onChange={e=>setField('title',e.target.value)}/></div><div className="grid gap-4 sm:grid-cols-2"><div><label className="mb-1.5 block text-sm font-medium" htmlFor="requirement-category">业务分类</label><select id="requirement-category" className="w-full rounded-md border border-slate-300 bg-white px-3 py-2 text-sm" value={draft.categoryId} onChange={e=>setField('categoryId',e.target.value)}><option value="">未分类</option>{categories.map(c=><option key={c.id} value={c.id}>{c.parentId?'— ':''}{c.name}</option>)}</select></div><div><label className="mb-1.5 block text-sm font-medium" htmlFor="requirement-industry">所属行业</label><Input id="requirement-industry" maxLength={60} value={draft.industry} onChange={e=>setField('industry',e.target.value)} placeholder="例如：医药流通、IVD、医院服务"/></div><div><label className="mb-1.5 block text-sm font-medium" htmlFor="requirement-department">使用部门</label><Input id="requirement-department" maxLength={60} value={draft.department} onChange={e=>setField('department',e.target.value)} placeholder="例如：采购部"/></div><div><label className="mb-1.5 block text-sm font-medium" htmlFor="requirement-difficulty">实现难度</label><select id="requirement-difficulty" className="w-full rounded-md border border-slate-300 bg-white px-3 py-2 text-sm" value={draft.difficulty} onChange={e=>setField('difficulty',e.target.value)}><option value="">未评估</option><option value="easy">简单</option><option value="medium">中等</option><option value="hard">复杂</option></select></div><div><label className="mb-1.5 block text-sm font-medium" htmlFor="requirement-status">实现状态</label><select id="requirement-status" className="w-full rounded-md border border-slate-300 bg-white px-3 py-2 text-sm" value={draft.implementationStatus} onChange={e=>setField('implementationStatus',e.target.value)}><option value="pending">待实现</option><option value="building">开发中</option><option value="completed">已实现</option><option value="verified">已验证</option></select></div><div className="sm:col-span-2"><label className="mb-1.5 block text-sm font-medium" htmlFor="requirement-outcome">预期效果</label><Textarea id="requirement-outcome" maxLength={3000} rows={3} value={draft.expectedOutcome} onChange={e=>setField('expectedOutcome',e.target.value)} placeholder="填写希望达到的业务结果"/></div></div></>}</fieldset><fieldset className="space-y-4 border-t p-4 md:p-6"><legend className="px-2 text-base font-semibold text-slate-900">需求说明</legend><RequirementDownloads id={selected.id} code={selected.requirementCode} version={selected.contentVersion}/>{draft&&<><div className="flex flex-wrap items-center justify-between gap-2"><p className="text-sm text-slate-600">使用 Markdown 记录需求背景、流程和验收要求。</p><Button type="button" size="sm" variant="outline" onClick={()=>setPreview(!preview)}>{preview?'继续编辑':'预览富文本'}</Button></div>{preview?<div className="min-h-48 rounded-md border bg-white p-4"><Markdown content={draft.content}/></div>:<Textarea aria-label="Markdown 需求说明" required minLength={5} maxLength={40000} rows={14} value={draft.content} onChange={e=>setField('content',e.target.value)} placeholder={'# 需求背景\n\n说明现状、目标和涉及人员。\n\n## 验收标准\n\n- 需要满足的结果'}/>}<p className="text-xs text-slate-500">支持标题、列表、链接、代码块和表格。HTML 标签不会执行。</p></>}</fieldset><div className="flex flex-wrap items-center gap-3 border-t bg-slate-50 px-4 py-3 md:px-6"><Button type="submit" disabled={saving||fileBusy||!draft||draft.title.trim().length<2||draft.content.trim().length<5}>{saving?'保存中…':'保存需求'}</Button><Button type="button" variant="outline" onClick={()=>setSelected(null)}>取消</Button>{notice&&<span role="status" className="text-sm text-green-700">{notice}</span>}<ErrorLine error={actionError}/></div></form><section className="rounded-lg border bg-white p-4 md:p-6"><Materials value={materials} onChange={setMaterials} onBusy={setFileBusy} review/><p className="mt-3 text-xs text-slate-500">先保存需求资料关联，再选择审核允许公开的文件。未勾选文件保持私有。</p></section><section className="rounded-lg border bg-white"><div className="border-b px-4 py-3 md:px-6"><h2 className="font-semibold">审核与发布</h2><p className="mt-1 text-sm text-slate-600">发布前检查公开正文、文件与共享授权；私有正文不会自动附加到下载材料。</p></div><div className="space-y-4 p-4 md:p-6"><div className="flex flex-wrap gap-2">{selected.images.map(im=><div key={im.id}><img src={im.url} alt="需求图片" className="h-28 rounded-md border"/>{selected.status==='submitted'&&<label className="mt-1 block text-xs"><input type="checkbox" checked={approved.includes(im.id)} onChange={e=>setApproved(current=>e.target.checked?[...current,im.id]:current.filter(x=>x!==im.id))}/> 审核通过该图片</label>}</div>)}</div><ReviewHistory item={selected}/>{selected.status==='submitted'?<><label className="block text-sm font-medium">脱敏案例摘要<Textarea className="mt-1.5" rows={3} value={summary} onChange={e=>setSummary(e.target.value)}/></label><label className="block text-sm font-medium">需求提示词<Textarea className="mt-1.5" rows={5} value={rprompt} onChange={e=>setRprompt(e.target.value)}/></label><label className="block text-sm font-medium">搭建提示词<Textarea className="mt-1.5" rows={5} value={bprompt} onChange={e=>setBprompt(e.target.value)}/></label><div className="flex flex-wrap items-center gap-3"><Button disabled={!selected.shareConsent||saving||fileBusy||!draft||draft.title.trim().length<2||draft.content.trim().length<5} onClick={async()=>{setSaving(true);setActionError('');try{await saveDraft();await post('/requirements/'+selected.id+'/review',{decision:'approve',title:draft?.title,summary,requirementPrompt:rprompt,buildPrompt:bprompt,approvedMediaIds:approved,approvedFileIds:materials.filter(f=>f.approved).map(f=>f.id)});await qc.invalidateQueries({queryKey:['requirements']});setNotice('审核已发布');setSelected(null);}catch(err:any){setActionError(err.message);}finally{setSaving(false);}}}>审核并发布</Button><label className="block w-full text-sm font-medium">退回原因（必填）<Textarea maxLength={3000} className="mt-1.5" value={rejectNotes} onChange={e=>setRejectNotes(e.target.value)} placeholder="请说明需要补充或修改的具体内容"/></label><Button disabled={saving||!rejectNotes.trim()} variant="outline" onClick={async()=>{setActionError('');try{await post('/requirements/'+selected.id+'/review',{decision:'reject',notes:rejectNotes});await qc.invalidateQueries({queryKey:['requirements']});setSelected(null);}catch(err:any){setActionError(err.message);}}}>退回修改</Button>{!selected.shareConsent&&<p className="text-sm text-amber-700">提交人未授权公开，不能发布为案例。</p>}<ErrorLine error={actionError}/></div></>:<p className="text-sm text-slate-600">该需求当前状态为“{selected.status}”，无需审核操作。</p>}</div></section></div>}
 </Panel>;
}
const usableKey=(k:any)=>!k.revokedAt&&(!k.expiresAt||k.expiresAt>Date.now()/1000);
const ordinaryKey=(k:any)=>usableKey(k)&&!k.scopes?.includes('taxonomy:write');
const scopeLabels:Record<string,string>={'requirements:read':'读取本人需求','requirements:write':'提交和修改本人需求','cases:read':'读取公开案例','taxonomy:read':'读取分类与标签','taxonomy:write':'维护分类与标签','media:read':'读取有权访问的附件','media:write':'上传附件'};
function KeyExpiry({value,onChange}:{value:number;onChange:(value:number)=>void}){return <label className="block text-sm font-medium">新密钥有效期<select className="mt-2 min-h-11 w-full rounded-md border border-slate-300 bg-white px-3 text-base" value={value} onChange={e=>onChange(Number(e.target.value))}>{[1,7,30,90].map(days=><option key={days} value={days}>{days} 天</option>)}</select></label>;}
function Keys(){
 const qc=useQueryClient();
 const{data=[],isLoading,error:loadError}=useData<any[]>('keys','/keys');
 const[error,setError]=useState(''),[busy,setBusy]=useState(false),[copied,setCopied]=useState(false),[days,setDays]=useState(30),[readOnly,setReadOnly]=useState(false);
 const active=data.find(ordinaryKey);
 const skill=active?.secretValue&&!active.legacy?agentSkillText(active.secretValue,active):'';
 const copy=async(text:string)=>{try{await navigator.clipboard.writeText(text);setCopied(true);setTimeout(()=>setCopied(false),1500);}catch{setError('复制失败，请选中文案手动复制。');}};
 return <Panel title="Agent 技能"><div className="space-y-5">
  <Card><CardContent className="space-y-4">
   <div><h2 className="font-semibold">API Key 权限与期限</h2><p className="mt-1 text-sm text-slate-600">普通 Agent 仅能访问本人需求、公开案例、分类标签和有权访问的附件。即使你是管理员，也不会授予用户管理或审核权限。</p></div>
   {isLoading?<p className="text-sm text-slate-600">正在读取密钥状态…</p>:loadError?<ErrorLine error={loadError}/>:active?<div className="space-y-2 text-sm text-slate-700"><p>当前密钥：<code className="rounded bg-slate-100 px-2 py-1">{active.prefix}…</code></p>{active.legacy?<p className="text-amber-800">旧版密钥待轮换：仍保留账号原有业务权限，未自动获得范围或到期保护。请更换后再交给 Agent。</p>:<><p>权限：{active.scopes.map((scope:string)=>scopeLabels[scope]??scope).join('、')}</p><p>到期时间：{new Date(active.expiresAt*1000).toLocaleString('zh-CN')}</p></>}</div>:<p className="text-sm text-amber-800">当前没有有效的普通 Agent 密钥，请生成新密钥。</p>}
   <div className="grid items-end gap-4 sm:grid-cols-2"><KeyExpiry value={days} onChange={setDays}/><label className="flex min-h-11 items-center gap-2 text-sm"><input type="checkbox" checked={readOnly} onChange={e=>setReadOnly(e.target.checked)}/>只读模式（不提交需求或上传附件）</label></div>
   <p className="text-sm text-slate-600">更换会立即撤销本账号所有旧密钥，包括分类标签管理密钥。新密钥加密保存，登录后可再次复制。</p>
   <Button variant="outline" disabled={busy||!!loadError||isLoading} onClick={async()=>{if(data.some(usableKey)&&!window.confirm('更换会立即撤销本账号所有旧密钥，包括管理技能密钥。确认继续吗？'))return;setBusy(true);setError('');try{const scopes=['requirements:read','cases:read','taxonomy:read','media:read',...(!readOnly?['requirements:write','media:write']:[])];await post('/keys/rotate',{scopes,expiresInDays:days});await qc.invalidateQueries();}catch(e:any){setError(e.message);}finally{setBusy(false);}}}><RefreshCw size={16}/>{busy?'正在更换…':'更换 API Key'}</Button>
   <ErrorLine error={error}/>
  </CardContent></Card>
  <section className="space-y-3"><div><h2 className="font-semibold">复制给你的 Agent</h2><p className="mt-1 text-sm text-slate-600">文案包含有效 API Key 明文，仅交给可信 Agent。到期或撤销后需重新复制新密钥。</p></div><Card><CardContent className="space-y-3">{skill?<><pre className="whitespace-pre-wrap break-all rounded-lg bg-slate-50 p-4 text-sm leading-relaxed">{skill}</pre><Button onClick={()=>copy(skill)}>{copied?<Check size={16}/>:<Copy size={16}/>} {copied?'已复制':'复制技能文案'}</Button></>:<p className="text-sm text-amber-800">请先更换为有权限范围和期限的新密钥。若无法生成或读取，请联系管理员配置 API_KEY_ENCRYPTION_KEY；已有业务访问不受配置缺失影响。</p>}</CardContent></Card></section>
 </div></Panel>;
}
function AdminCases(){const{items:data,controls}=usePage<Case>('admin-cases','/cases?scope=all');const qc=useQueryClient();const[title,setTitle]=useState(''),[summary,setSummary]=useState(''),[requirementPrompt,setRequirementPrompt]=useState(''),[buildPrompt,setBuildPrompt]=useState('');const[editing,setEditing]=useState<Case|null>(null);const[error,setError]=useState('');return <Panel title="案例管理"><Card><CardContent className="space-y-3"><h2 className="font-medium">{editing?'编辑案例':'新建独立案例'}</h2><Input placeholder="案例标题" value={title} onChange={e=>setTitle(e.target.value)}/><Textarea placeholder="脱敏后的公开简介" value={summary} onChange={e=>setSummary(e.target.value)}/><Textarea placeholder="需求提示词" value={requirementPrompt} onChange={e=>setRequirementPrompt(e.target.value)}/><Textarea placeholder="搭建提示词" value={buildPrompt} onChange={e=>setBuildPrompt(e.target.value)}/><ErrorLine error={error}/>{editing&&<CaseMaterials key={editing.id} item={editing}/>}<Button onClick={async()=>{setError('');try{if(editing)await patch('/cases/'+editing.id,{title,summary,requirementPrompt,buildPrompt});else await post('/cases',{title,summary,requirementPrompt,buildPrompt});setEditing(null);setTitle('');setSummary('');setRequirementPrompt('');setBuildPrompt('');qc.invalidateQueries();}catch(e:any){setError(e.message);}}}>保存草稿</Button></CardContent></Card>{controls}{data.map(c=><Card key={c.id}><CardContent className="flex flex-wrap justify-between gap-3"><div><b>{c.title}</b><p className="text-sm text-slate-500">{c.status}</p></div><div className="flex gap-2"><Button variant="outline" size="sm" onClick={async()=>{const full=await api<Case>('/cases/'+c.id);setEditing(full);setTitle(full.title);setSummary(full.summary);setRequirementPrompt(full.prompts?.find(p=>p.type==='requirement')?.content??'');setBuildPrompt(full.prompts?.find(p=>p.type==='build')?.content??'');window.scrollTo(0,0);}}>编辑</Button><Button size="sm" onClick={async()=>{await post('/cases/'+c.id+'/status',{status:c.status==='published'?'archived':'published'});qc.invalidateQueries();}}>{c.status==='published'?'下架':'发布'}</Button></div></CardContent></Card>)}</Panel>;}
function AdminUsers({user}:{user:User}){
  const{items:data,controls}=usePage<any>('users','/users');const qc=useQueryClient();
  const[pending,setPending]=useState<string|null>(null);
  const roleLabels:Record<string,string>={student:'学员',reviewer:'审核员',admin:'管理员',super_admin:'超级管理员'};
  const{data:facets}=useData<{activeSupers:number}>('users','/users/facets');
  const activeSupers=facets?.activeSupers??0;
  const restriction=(u:any)=>{
    if(u.role==='super_admin'&&u.status==='active'&&activeSupers<=1)return '须保留最后一名启用的超级管理员';
    if(u.id===user.id)return '不能移除自己的访问权限';
    if(user.role==='admin'&&!['student','reviewer'].includes(u.role))return '管理员只能管理学员和审核员';
    if(!['admin','super_admin'].includes(user.role))return '仅管理员可管理用户';
    return '';
  };
  const update=async(u:any,changes:{role?:string;status?:string})=>{
    setPending(u.id);
    try{await patch('/users/'+u.id,changes);}catch(error:any){alert(error.message);}
    finally{await qc.invalidateQueries({queryKey:['users']});setPending(null);}
  };
  return <Panel title="用户管理">{controls}<Card><CardContent className="overflow-auto"><table className="w-full min-w-[640px] text-sm"><thead><tr className="text-left border-b"><th className="py-3">用户邮箱</th><th>角色</th><th>状态</th><th>管理</th></tr></thead><tbody>{data.map(u=>{
    const reason=restriction(u);const hintId=`user-restriction-${u.id}`;
    return <tr key={u.id} className="border-b"><td className="py-3">{u.email}</td><td>{user.role==='super_admin'?<select aria-label={`修改 ${u.email} 的角色`} aria-describedby={reason?hintId:undefined} disabled={!!reason||pending!==null} className="rounded-md border border-slate-300 bg-white px-2 py-1.5 disabled:opacity-50" value={u.role} onChange={e=>update(u,{role:e.target.value})}><option value="student">学员</option><option value="reviewer">审核员</option><option value="admin">管理员</option>{u.role==='super_admin'&&<option value="super_admin" disabled>超级管理员</option>}</select>:roleLabels[u.role]??u.role}</td><td>{u.status}</td><td className="py-3"><Button size="sm" variant="outline" disabled={!!reason||pending!==null} aria-describedby={reason?hintId:undefined} onClick={()=>{if(confirm('确认修改用户状态？'))void update(u,{status:u.status==='active'?'disabled':'active'});}}>{pending===u.id?'保存中…':u.status==='active'?'禁用':'启用'}</Button>{reason&&<p id={hintId} className="mt-1 max-w-52 text-xs text-slate-600">{reason}</p>}</td></tr>;
  })}</tbody></table></CardContent></Card></Panel>;
}
function AdminMedia(){
 const qc=useQueryClient();const[uploads,setUploads]=useState<Material[]>([]),[fileSearch,setFileSearch]=useState(''),[filePurpose,setFilePurpose]=useState('');
 const{items:documents,controls:documentControls}=usePage<Material>('all-files','/files?scope=all',Object.fromEntries(Object.entries({q:fileSearch,purpose:filePurpose}).filter(([,v])=>v)));
 const{items:data,controls}=usePage<any>('media','/media');
 return <Panel title="图片与资料"><p className="text-sm text-slate-500">原始图片与文件受访问控制。上传后，在需求或案例编辑页选择资料完成关联与审核。</p><Card><CardContent><Materials value={uploads} onChange={v=>{setUploads(v);qc.invalidateQueries({queryKey:['all-files']});}}/></CardContent></Card><section aria-label="文件资料列表" className="space-y-3"><h2 className="font-semibold">已上传文件资料</h2><div className="flex flex-wrap gap-2"><Input aria-label="搜索文件资料" className="sm:max-w-sm" placeholder="搜索文件名" value={fileSearch} onChange={e=>setFileSearch(e.target.value)}/><select aria-label="文件资料用途" className="rounded-md border bg-white p-2 text-sm" value={filePurpose} onChange={e=>setFilePurpose(e.target.value)}><option value="">全部用途</option><option value="reference">案例参考资料</option><option value="agent">Agent 需求文档</option><option value="data">数据样例</option><option value="other">其他材料</option></select></div>{documentControls}<MaterialList value={documents}/></section><section aria-label="历史图片列表" className="space-y-3"><h2 className="font-semibold">历史图片资源</h2>{controls}<div className="grid sm:grid-cols-3 lg:grid-cols-4 gap-4">{data.map(m=><Card key={m.id}><CardContent><img alt="媒体资源图片" src={'/api/media/'+m.id+'/content'} className="w-full h-36 object-contain"/><div className="text-xs text-slate-500 mt-2">{m.status} · {Math.round(m.size/1024)}KB</div></CardContent></Card>)}</div></section></Panel>;
}
function AdminCategories({editable=true}:{editable?:boolean}){const{data=[],error}=useData<any[]>('categories','/categories');const qc=useQueryClient();const[name,setName]=useState(''),[slug,setSlug]=useState(''),[parentId,setParentId]=useState(''),[sortOrder,setSortOrder]=useState(0),[editingId,setEditingId]=useState<string|null>(null),[actionError,setActionError]=useState('');const reset=()=>{setName('');setSlug('');setParentId('');setSortOrder(0);setEditingId(null)};return <Panel title="分类管理">{editable&&<Card><CardContent className="flex flex-wrap gap-3"><Input className="sm:w-44" placeholder="分类名称" value={name} onChange={e=>setName(e.target.value)}/><Input className="sm:w-44" placeholder="英文 slug" value={slug} onChange={e=>setSlug(e.target.value)}/><select className="border rounded-md px-3" value={parentId} onChange={e=>setParentId(e.target.value)}><option value="">一级分类</option>{data.filter(c=>c.id!==editingId).map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select><Input className="sm:w-24" type="number" aria-label="排序值" value={sortOrder} onChange={e=>setSortOrder(Number(e.target.value))}/><Button onClick={async()=>{try{if(editingId)await patch('/categories/'+editingId,{name,slug,parentId:parentId||null,sortOrder});else await post('/categories',{name,slug,parentId:parentId||null,sortOrder});reset();setActionError('');qc.invalidateQueries()}catch(e:any){setActionError(e.message)}}}>{editingId?'保存分类':'添加分类'}</Button>{editingId&&<Button variant="outline" onClick={reset}>取消</Button>}</CardContent></Card>}<ErrorLine error={error||actionError}/><div className="space-y-2">{data.map(c=><div key={c.id} className="bg-white border rounded-md p-3 text-sm flex flex-wrap items-center justify-between gap-2"><span>{c.parentId?'— ':''}{c.name} <span className="text-slate-400">/{c.slug} · {c.sortOrder}</span></span>{editable&&<div className="flex gap-2"><Button size="sm" variant="outline" onClick={()=>{setEditingId(c.id);setName(c.name);setSlug(c.slug);setParentId(c.parentId??'');setSortOrder(c.sortOrder);setActionError('');window.scrollTo(0,0)}}>编辑</Button><Button size="sm" variant="outline" onClick={async()=>{try{if(!confirm('删除此分类？被需求、案例或子分类使用时无法删除。'))return;await api('/categories/'+c.id,{method:'DELETE'});qc.invalidateQueries()}catch(e:any){setActionError(e.message)}}}>删除</Button></div>}</div>)}</div></Panel>;}
function AdminSkill(){
 const qc=useQueryClient();const{data:skill,error}=useData<{content:string}>('admin-skill','/admin/skill');const{data:keys=[]}=useData<any[]>('admin-skill-keys','/keys');
 const activeKey=keys.find(k=>usableKey(k)&&k.scopes?.includes('taxonomy:write')&&k.secretValue);
 const[copied,setCopied]=useState(false),[errorCopy,setErrorCopy]=useState(''),[busy,setBusy]=useState(false),[days,setDays]=useState(30);
 const text=(skill?.content.replace('<管理员自己的 API Key>',activeKey?.secretValue??'<请先生成分类标签管理密钥>')??'')+(activeKey?'\n\n- 权限范围：taxonomy:read、taxonomy:write；无用户管理、审核或发布权限。\n- 到期时间：'+new Date(activeKey.expiresAt*1000).toLocaleString('zh-CN'):'');
 return <Panel title="管理 Agent 技能"><Card><CardContent className="space-y-4"><p className="text-sm text-slate-600">显式生成仅可维护分类与标签的密钥。不会授予用户管理、需求审核或案例发布权限，也不会替换普通 Agent 密钥。</p><KeyExpiry value={days} onChange={setDays}/><Button disabled={busy||!!error} variant="outline" onClick={async()=>{setBusy(true);setErrorCopy('');try{await post('/keys/taxonomy',{expiresInDays:days});await qc.invalidateQueries();}catch(e:any){setErrorCopy(e.message);}finally{setBusy(false);}}}>{busy?'正在生成…':'生成 / 更换分类标签管理密钥'}</Button><ErrorLine error={error}/>{activeKey?<><p className="text-sm text-slate-700">权限：读取和维护分类与标签；到期：{new Date(activeKey.expiresAt*1000).toLocaleString('zh-CN')}</p><pre className="whitespace-pre-wrap break-all rounded-lg bg-slate-50 p-4 text-sm leading-relaxed">{text}</pre><Button onClick={async()=>{try{await navigator.clipboard.writeText(text);setCopied(true);setErrorCopy('');setTimeout(()=>setCopied(false),1500);}catch{setErrorCopy('复制失败，请选中文案手动复制。');}}}>{copied?<Check size={16}/>:<Copy size={16}/>} {copied?'已复制':'复制管理技能'}</Button></>:<p className="text-sm text-amber-800">尚无有效的分类标签管理密钥。请先生成，再复制给可信 Agent。</p>}<ErrorLine error={errorCopy}/></CardContent></Card></Panel>;
}
function Dashboard(){const{data}=useData<any>('stats','/stats');return <Panel title="平台数据概览"><p className="text-slate-600">医疗大健康及医药领域需求平台 · 管理需求、审核资料与维护参考案例。</p><div className="grid grid-cols-2 lg:grid-cols-4 gap-4">{[['注册用户',data?.users],['原始需求',data?.requirements],['案例总数',data?.cases],['待审核需求',data?.pending]].map(([label,value])=><Card key={label}><CardContent><p className="text-sm text-slate-500">{label}</p><p className="text-3xl font-bold mt-2">{value??'—'}</p></CardContent></Card>)}</div><Link to="/admin/requirements"><Button>进入需求审核 <ChevronRight size={16}/></Button></Link></Panel>;}
function NotFound(){return <div className="min-h-[70vh] flex flex-col items-center justify-center gap-4 text-center"><img src="/brand/404.webp" alt="404 页面走丢了" className="w-full max-w-xl rounded-xl"/><Link to="/" className="rounded-lg bg-orange-500 text-white px-5 py-2.5 text-sm">返回需求案例库</Link></div>;}
export default function App(){const{data:user,isLoading,refetch}=useQuery<User|null>({queryKey:['me'],queryFn:()=>api<User>('/me').catch(()=>null),retry:false});const nav=useNavigate();if(isLoading)return <div className="p-10 text-slate-500">载入中...</div>;if(!user)return <Routes><Route path="/" element={<Landing/>}/><Route path="/login" element={<Auth onLogin={()=>{refetch();nav('/');}}/>}/><Route path="/register" element={<Auth onLogin={()=>{refetch();nav('/');}}/>}/><Route path="*" element={<Navigate to="/"/>}/></Routes>;const logout=async()=>{await post('/auth/logout',{});await refetch();nav('/');};return <Routes><Route path="/admin/*" element={['admin','super_admin','reviewer'].includes(user.role)?<Shell admin user={user} onLogout={logout}><Routes><Route index element={<Dashboard/>}/><Route path="requirements" element={<Requirements admin/>}/><Route path="cases" element={<AdminCases/>}/><Route path="users" element={<AdminUsers user={user}/>}/><Route path="media" element={<AdminMedia/>}/><Route path="categories" element={<AdminCategories editable={user.role==='admin'||user.role==='super_admin'}/>}/><Route path="tags" element={<AdminTags editable={user.role==='admin'||user.role==='super_admin'}/>}/><Route path="skill" element={user.role==='admin'||user.role==='super_admin'?<AdminSkill/>:<Navigate to="/admin"/>}/></Routes></Shell>:<Navigate to="/"/>}/><Route path="/*" element={<Shell user={user} admin={false} onLogout={logout}><Routes><Route index element={<Catalog/>}/><Route path="cases/:id" element={<CaseDetail/>}/><Route path="submit" element={<Submit/>}/><Route path="mine" element={<Requirements/>}/><Route path="mine/:id/edit" element={<EditMyRequirement/>}/><Route path="keys" element={<Keys/>}/><Route path="*" element={<NotFound/>}/></Routes></Shell>}/></Routes>;}
